"use client";

/**
 * Whip pan transition: the camera snaps sideways, both scenes travel together
 * and smear with horizontal motion blur at the peak of the move. Use it for a
 * quick change of subject.
 *
 * Written by Better Design. A presentation for `<TransitionSeries.Transition>`,
 * plus `WhipPanDemo`, two theme-coloured cards that play it.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { linearTiming, TransitionSeries, type TransitionPresentation, type TransitionPresentationComponentProps } from "@remotion/transitions";
import { AbsoluteFill, Easing } from "remotion";
import { pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";
import { useId } from "react";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600"], subsets: ["latin"] });

export type WhipPanProps = {
  /** Which way the camera turns. "left" moves the frame content to the left. */
  direction?: "left" | "right";
  /** Peak horizontal blur in pixels, reached at the middle of the move. */
  blur?: number;
};

function WhipPanPresentation({ children, presentationDirection, presentationProgress: p, passedProps }: TransitionPresentationComponentProps<WhipPanProps>) {
  const { direction = "left", blur = 60 } = passedProps;
  const id = useId().replace(/[^a-zA-Z0-9-]/g, "");
  const sign = direction === "left" ? -1 : 1;
  // Both scenes sit on one strip: the outgoing one leaves as the next one arrives.
  const x = presentationDirection === "exiting" ? sign * p * 100 : -sign * (1 - p) * 100;
  // Blur follows speed, which peaks in the middle of an eased move.
  const amount = blur * Math.sin(Math.PI * p) ** 2;
  return (
    <AbsoluteFill style={{ transform: `translateX(${x}%)` }}>
      <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden>
        <filter id={`whip-${id}`} x="-20%" y="0" width="140%" height="100%">
          <feGaussianBlur stdDeviation={`${amount} 0`} />
        </filter>
      </svg>
      <AbsoluteFill style={{ filter: amount > 0.5 ? `url(#whip-${id})` : undefined }}>{children}</AbsoluteFill>
    </AbsoluteFill>
  );
}

/** Snap the camera sideways, with both scenes moving together under directional motion blur. */
export function whipPan(props: WhipPanProps = {}): TransitionPresentation<WhipPanProps> {
  return { component: WhipPanPresentation, props };
}

export interface WhipPanDemoProps {
  /** Title on the first card. */
  fromTitle?: string;
  /** Title on the second card. */
  toTitle?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

function DemoCard({ title, step, ink, muted, surface, page, line, family }: { title: string; step: string; ink: string; muted: string; surface: string; page: string; line: string; family: string }) {
  return (
    <AbsoluteFill style={{ background: page, alignItems: "center", justifyContent: "center", fontFamily: family }}>
      <div style={{ width: 1120, height: 600, borderRadius: 36, background: surface, border: `2px solid ${line}`, padding: 88, display: "flex", flexDirection: "column", justifyContent: "space-between" }}>
        <div style={{ fontSize: 30, fontWeight: 500, color: muted, letterSpacing: "0.02em" }}>{step}</div>
        <div style={{ fontSize: 112, fontWeight: 600, letterSpacing: "-0.04em", lineHeight: 1, color: ink }}>{title}</div>
        <div style={{ display: "flex", gap: 16 }}>
          <div style={{ width: 260, height: 18, borderRadius: 9, background: withAlpha(ink, 0.14) }} />
          <div style={{ width: 160, height: 18, borderRadius: 9, background: withAlpha(ink, 0.08) }} />
        </div>
      </div>
    </AbsoluteFill>
  );
}

/** Two cards with the transition between them, for the gallery. 90 frames. */
export function WhipPanDemo({ fromTitle = "Where it starts", toTitle = "Where it lands", theme: themeOverride, font }: WhipPanDemoProps) {
  const t = useVideoTheme(themeOverride);
  const family = pickFont(font, t, INTER);
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={44}>
        <DemoCard title={fromTitle} step="01" ink={t.cardForeground} muted={t.mutedForeground} surface={t.card} page={t.background} line={t.border} family={family} />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition presentation={whipPan({ direction: "left" })} timing={linearTiming({ durationInFrames: 18, easing: Easing.bezier(0.7, 0, 0.3, 1) })} />
      <TransitionSeries.Sequence durationInFrames={64}>
        <DemoCard title={toTitle} step="02" ink={t.primaryForeground} muted={withAlpha(t.primaryForeground, 0.7)} surface={withAlpha(t.primaryForeground, 0.08)} page={t.primary} line={withAlpha(t.primaryForeground, 0.22)} family={family} />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
}
